    internal static int FdtPar(emon.Port.Cells nodes, emon.Port.Cells regions, emon.Port.Cells text, byte[] b, int x0, int y0, int x1, int y1) {
        // A paragraph under the document, with this text and this box on page 1.
        int n = Model.NodeNew(nodes, Model.NkParagraph(), 0);
        int s = Model.TextLen(text);
        Model.TextAppendUtf8(text, b, 0, emon.Port.BlobLen(b));
        Model.NodeSetText(nodes, n, s, Model.TextLen(text) - s);
        Model.NodeAddRegion(nodes, regions, n, 1, x0, y0, x1, y1);
        return n;
    }
    internal static int FdtRun(emon.Port.Cells txt, byte[] b) {
        // Append b to the annotation text and answer where it starts.
        int s = emon.Port.CellsLen(txt);
        Model.TextAppendUtf8(txt, b, 0, emon.Port.BlobLen(b));
        return s;
    }
    internal static int FdtField(emon.Port.Cells an, emon.Port.Cells txt, int kind, int @checked, byte[] name, byte[] value, byte[] export, int x0, int y0, int x1, int y1) {
        // One `an-field` row (the layout is in the head of `emon.pdfannot`) on page 1: kind 2 check box, 3 radio, 4 text; `checked` for a button; the strings may be empty.
        int at = emon.Port.CellsLen(an);
        int ns = FdtRun(txt, name);
        int vs = FdtRun(txt, value);
        int es = FdtRun(txt, export);
        int k = 0;
        while (k < 38) {
            emon.Port.CellsPush(an, 0);
            k += 1;
        }
        emon.Port.CellsSet(an, at + 1, Pdfannot.AnField());
        emon.Port.CellsSet(an, at + 4, x0);
        emon.Port.CellsSet(an, at + 5, y0);
        emon.Port.CellsSet(an, at + 6, x1);
        emon.Port.CellsSet(an, at + 7, y1);
        emon.Port.CellsSet(an, at + 8, kind);
        emon.Port.CellsSet(an, at + 9, @checked);
        emon.Port.CellsSet(an, at + 11, 1);
        emon.Port.CellsSet(an, at + 12, ns);
        emon.Port.CellsSet(an, at + 13, emon.Port.BlobLen(name));
        emon.Port.CellsSet(an, at + 14, -1);
        emon.Port.CellsSet(an, at + 16, -1);
        emon.Port.CellsSet(an, at + 18, -1);
        if (emon.Port.BlobLen(value) > 0) {
            emon.Port.CellsSet(an, at + 14, vs);
            emon.Port.CellsSet(an, at + 15, emon.Port.BlobLen(value));
        }
        if (emon.Port.BlobLen(export) > 0) {
            emon.Port.CellsSet(an, at + 16, es);
            emon.Port.CellsSet(an, at + 17, emon.Port.BlobLen(export));
        }
        return 0;
    }
