    [Xunit.Fact]
    public static void TestALabelWithStyledWordsHasNoTextOfItsOwnAndStillHoldsAField() {
        // The W-9's `1 Name of entity` is a bold `1` and the words after it: the paragraph has no text run, its words are its inline children's. It is a label all the same (its
        // words are the children's), the field under it comes after the last of them, and the children are kept.
        emon.Port.Cells nodes = emon.Port.NewCells();
        emon.Port.Cells attrs = emon.Port.NewCells();
        emon.Port.Cells regions = emon.Port.NewCells();
        emon.Port.Cells text = emon.Port.NewCells();
        emon.Port.Cells pages = emon.Port.NewCells();
        emon.Port.Cells ledger = emon.Port.NewCells();
        emon.Port.Cells layout = emon.Port.NewCells();
        emon.Port.Cells an = emon.Port.NewCells();
        emon.Port.Cells txt = emon.Port.NewCells();
        System.Text.StringBuilder @out = emon.Testport.NewText();
        Model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout);
        int p = Model.NodeNew(nodes, Model.NkParagraph(), 0);
        int sp = Model.NodeNew(nodes, Model.NkSpan(), p);
        int t1 = Model.NodeNew(nodes, Model.NkText(), sp);
        int t2 = Model.NodeNew(nodes, Model.NkText(), p);
        int s1 = Model.TextLen(text);
        Model.NodeSetSub(nodes, sp, 1);
        Model.TextAppendUtf8(text, emon.Testport.TextBlob("1"), 0, 1);
        Model.NodeSetText(nodes, t1, s1, 1);
        Model.TextAppendUtf8(text, emon.Testport.TextBlob(" Name of entity"), 0, 15);
        Model.NodeSetText(nodes, t2, s1 + 1, 15);
        Model.NodeAddRegion(nodes, regions, p, 1, 6200, 9700, 27400, 11400);
        FdtField(an, txt, 4, -1, emon.Testport.TextBlob("f1_01[0]"), emon.Testport.TextBlob(""), emon.Testport.TextBlob(""), 5860, 11800, 57600, 13200);
        FdtHtml(0, nodes, attrs, regions, text, an, txt, @out);
        emon.Testport.AssertText(@out, "<!doctype html><html><head><meta charset=\"utf-8\"><title></title></head><body><main><p><b>1</b> Name of entity<span data-emon=\"field\" data-emon-name=\"f1_01[0]\" data-emon-type=\"text\"></span></p></main></body></html>", "after the last inline");
    }
