        int rg = Model.NodeNew(nodes, Model.NkRowgroup(), tb);
        int rw = Model.NodeNew(nodes, Model.NkRow(), rg);
        int c1 = Model.NodeNew(nodes, Model.NkCell(), rw);
        int c2 = Model.NodeNew(nodes, Model.NkCell(), rw);
        int s = Model.TextLen(text);
        Model.NodeSetSub(nodes, rg, 2);
        Model.NodeSetAux(nodes, c1, 1);
        Model.NodeAddRegion(nodes, regions, c1, 1, 3600, 6000, 5200, 7000);
        Model.TextAppendUtf8(text, emon.Testport.TextBlob("Total"), 0, 5);
        Model.NodeSetText(nodes, c2, s, 5);
        Model.NodeAddRegion(nodes, regions, c2, 1, 20000, 6000, 30000, 7000);
        FdtField(an, txt, 2, 0, emon.Testport.TextBlob("inbox"), emon.Testport.TextBlob(""), emon.Testport.TextBlob("1"), 3900, 6200, 4900, 6800);
        FdtHtml(0, nodes, attrs, regions, text, an, txt, @out);
        emon.Testport.AssertText(@out, "<!doctype html><html><head><meta charset=\"utf-8\"><title></title></head><body><main><table><tbody><tr><td><span data-emon=\"field\" data-emon-name=\"inbox\" data-emon-type=\"checkbox\" role=\"checkbox\" data-emon-checked=\"false\" aria-checked=\"false\" data-emon-value=\"1\"></span></td><td>Total</td></tr></tbody></table></main></body></html>", "in the cell");
    }
