    [Xunit.Fact]
    public static void TestTheW9sEightBoxesAndFifteenTextFieldsLandBesideTheirLabels() {
        // The W-9's first page: each of the seven boxes of 3a is before the label to its right (the first is on, so it says so and its value is the export value), the
        // LLC box before the LLC line and the letter box after it (the label above it is nearer by 4 pt, the one to its left by 7.6: the left one stays), `Other` and its box,
        // the box of 3b after the line it ends (the dot leaders join them), the name field after the name label (it has a value), the address, the requester, the city, the account
        // number after their labels above them, the three boxes of the number after `Social security number` and the two of the EIN after theirs; and no field is left over.
        emon.Port.Cells nodes = emon.Port.NewCells();
        emon.Port.Cells attrs = emon.Port.NewCells();
        emon.Port.Cells regions = emon.Port.NewCells();
        emon.Port.Cells text = emon.Port.NewCells();
        emon.Port.Cells pages = emon.Port.NewCells();
        emon.Port.Cells ledger = emon.Port.NewCells();
        emon.Port.Cells layout = emon.Port.NewCells();
        emon.Port.Cells an = emon.Port.NewCells();
